SELECT w.id AS wallet_trade_id, w.symbol, w.execution_reason, w.executed_at, s1.id AS s1m_id, s1.generated_at AS s1m_gen, s5.id AS s5m_id, s5.generated_at AS s5m_gen, s5.decision AS s5m_decision, TIMESTAMPDIFF(MICROSECOND, s1.generated_at, s5.generated_at) AS s5m_after_1m_us FROM wallet_trade w JOIN trade_signal s1 ON s1.id = w.signal_id AND s1.interval_code = '1m' JOIN trade_signal s5 ON s5.symbol = s1.symbol AND s5.interval_code = '5m' AND s5.candle_open_time = s1.candle_open_time - INTERVAL 4 MINUTE WHERE w.side = 'BUY' AND w.executed_at >= '2026-10-01 00:00:00' AND MINUTE(s1.candle_open_time) % 5 = 4 ORDER BY w.executed_at LIMIT 200